create or replace function public.decline_registration_request(p_registration uuid,p_admin uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_status text; v_claim_token uuid; v_claimed_at timestamptz; v_admin_role text; v_reason text:=btrim(coalesce(p_reason,'')); begin select role into v_admin_role from public.admins where id=p_admin; if coalesce(v_admin_role,'') not in ('admin','super_admin') then raise exception 'Not authorized'; end if; if char_length(v_reason)<3 then raise exception 'Decline reason is required'; end if; if char_length(v_reason)>500 then raise exception 'Decline reason must be 500 characters or fewer'; end if; select status,approval_claim_token,approval_claimed_at into v_status,v_claim_token,v_claimed_at from public.registration_requests where id=p_registration for update; if not found then return jsonb_build_object('declined',false,'reason','not_found'); end if; if v_status is distinct from 'pending' then return jsonb_build_object('declined',false,'reason','already_reviewed','status',v_status); end if; if v_claim_token is not null and v_claimed_at is not null and v_claimed_at>now()-interval '15 minutes' then return jsonb_build_object('declined',false,'reason','approval_in_progress','claimed_at',v_claimed_at); end if; update public.registration_requests set status='declined',decline_reason=v_reason,reviewed_by=p_admin,reviewed_at=now() where id=p_registration; return jsonb_build_object('declined',true,'reason','declined'); end $$; revoke all on function public.decline_registration_request(uuid,uuid,text) from public,anon,authenticated; grant execute on function public.decline_registration_request(uuid,uuid,text) to service_role;;
